from collections import Counter
class Solution:
 def divideArray(self,nums):
  return all(v%2==0 for v in Counter(nums).values())

class Solution:
 def countHillValley(self,nums):
  a=[]
  for x in nums:
   if not a or a[-1]!=x:a.append(x)
  return sum((a[i]>a[i-1] and a[i]>a[i+1]) or (a[i]<a[i-1] and a[i]<a[i+1]) for i in range(1,len(a)-1))

class Solution:
 def findDifference(self,nums1,nums2):
  a,b=set(nums1),set(nums2)
  return [list(a-b),list(b-a)]

class Solution:
 def convertTime(self,current,correct):
  def mins(s):
   h,m=map(int,s.split(':'));return h*60+m
  d=mins(correct)-mins(current);ans=0
  for step in (60,15,5,1):ans+=d//step;d%=step
  return ans

class Solution:
 def digitSum(self,s,k):
  while len(s)>k:s=''.join(str(sum(map(int,s[i:i+k]))) for i in range(0,len(s),k))
  return s
